'use strict';
const categories = {thinking:'清晰思考',communication:'从容沟通',resilience:'压力与恢复',humor:'幽默表达'};
const scenarios = [
 {id:'challenge',type:'communication',title:'当你的方案被当众质疑',quote:'“你这个方案，根本没考虑清楚。”',context:'项目会上，同事打断了你的介绍。大家都在看着你，你有些委屈，也有些生气。你希望讨论回到具体问题上。',prompt:'你会怎样回应？写下你真正会说的话。',example:'我想把问题具体弄清楚。你最担心的是时间安排，还是方案效果？我们可以先看最关键的一点，再决定怎么调整。',action:'下一次遇到笼统的质疑，先问一个具体问题，再解释自己的立场。',checks:[['澄清具体问题','具体|哪|什么|担心|指的是|举例|\?|？','尝试问：你最担心的是哪一部分？'],['提出下一步','先|一起|讨论|调整|确认|建议|可以|我们','提出一个可执行的下一步，让讨论继续。'],['避免对抗性归因','你总是|你从来|你懂什么|闭嘴|故意|针对我','检查有没有把对方的动机当成事实。',true]]},
 {id:'refuse',type:'communication',title:'温和，但明确地拒绝',quote:'“这个你顺手帮我做了吧，今晚就要。”',context:'你今天已经排满任务。朋友临时请求帮忙，你不想勉强答应后又失约，也希望维护关系。',prompt:'怎样表达你的边界，同时尊重对方？',example:'我知道你今晚急着要，但我今天已经安排满了，没法替你做完。如果有帮助，我明天可以用十分钟帮你看看思路。',action:'找一件不适合答应的小事，清楚表达自己的时间或能力边界。',checks:[['表达明确的边界','不能|没法|无法|不方便|做不了|安排满|不行','把“可能有点忙”换成清楚的边界。'],['认可对方的处境','知道|理解|着急|急|明白','用一句话承认对方的需要，不必为拒绝过度解释。'],['尊重彼此','你总是|活该|烦死|别来找我','去掉指责，直接说自己的安排和决定。',true]]},
 {id:'evidence',type:'thinking',title:'大家都在说，就一定对吗？',quote:'“我身边的人都靠这个方法提高了效率，所以它肯定适合所有人。”',context:'你看到一个非常自信的效率建议。你想判断这项建议是否值得尝试，而不是马上接受或否定。',prompt:'这里有哪些证据、假设和遗漏？你会怎样验证？',example:'目前的依据是身边人的经验，但样本可能经过筛选，也没有比较没用这个方法的人。效率具体指什么？我会先选一个任务试一周，记录耗时和质量，再和原来的做法比较。',action:'今天遇到一个绝对化的结论时，问：什么证据会让我改变判断？',checks:[['检查证据范围','样本|身边|个例|代表|偏差|证据|幸存','检查身边人的经验能否代表其他情境。'],['找到替代解释','也可能|其他|原本|不一定|假设|比较|对照','提出至少一种其他解释或被忽略的条件。'],['设计可验证的行动','试|记录|比较|验证|一周|指标|测试','设计一个有观察指标的小实验。']]},
 {id:'decision',type:'thinking',title:'在两个选择之间做决定',quote:'“薪资高的工作，肯定更值得去。”',context:'你拿到了两份 offer。一份薪资更高但通勤长，另一份收入略低，但能学到你感兴趣的技能。',prompt:'你会怎样拆解这个决定？还缺少什么信息？',example:'我先明确自己未来一年的目标：积累技能，同时保持可持续的作息。比较税后收入、通勤时间、管理方式和学习机会。我还需要和未来同事确认实际加班情况，再按自己的优先级权衡。',action:'为一个待决定的问题写出三个重要标准，并注明还缺少的信息。',checks:[['明确个人目标','目标|优先|在意|想要|重要|价值','先确定你希望这个决定帮你实现什么。'],['考虑多个维度','时间|通勤|学习|成长|团队|健康|作息','至少考虑一个薪资之外的维度。'],['识别未知信息','确认|了解|信息|询问|还需要|不确定|问','列出一个决定前值得核实的问题。']]},
 {id:'setback',type:'resilience',title:'努力之后，结果还是不理想',quote:'“准备了这么久还是失败，是不是我根本不行？”',context:'一次重要面试没有通过。你很失落，开始把一次结果理解成对自己的整体评价。',prompt:'把事实、感受和解释分开，再写一个你愿意做的小行动。',example:'事实是这一次没有通过，我现在失落、沮丧。但我还不知道具体原因，一次结果不能解释我的全部能力。今晚先休息，明天整理答得不清楚的一个问题，找朋友模拟练一次。',action:'选一个最近的挫折，写下一个可控因素和一个足够小的下一步。',checks:[['区分结果与自我评价','这次|一次|事实|不代表|不能说明|结果','把“我不行”改成这次具体发生了什么。'],['允许情绪和恢复','失落|难过|沮丧|休息|恢复|情绪|朋友|求助','给感受一个名字，安排休息或支持。'],['提出可控的小行动','明天|整理|复盘|练|下一步|一个|反馈','选一个小到能开始的行动。']]},
 {id:'pressure',type:'resilience',title:'事情一多，就不知道从哪里开始',quote:'“今天这三件事都很急，我感觉要撑不住了。”',context:'你同时遇到三个截止日期，注意力不断跳转。你需要先恢复一点秩序，再处理工作量。',prompt:'你准备如何安排接下来的十分钟？',example:'先停一分钟，喝水，让呼吸慢下来。把三件事的截止时间、影响和工作量写下来，选最关键的一件开始做十分钟。如果确实来不及，尽早和相关的人讨论延期或减少范围。',action:'压力上来时，写出：现在最重要的一件事、下一步、需要谁帮助。',checks:[['先稳定当下','停|呼吸|喝水|休息|慢下来','先给自己一个短暂停顿，再安排任务。'],['具体化优先级','重要|截止|影响|优先|一件|排序','按截止时间和影响选出一件优先任务。'],['调整资源或范围','帮助|求助|沟通|延期|范围|讨论|协商','必要时沟通容量，争取帮助或调整范围。']]},
 {id:'humor',type:'humor',title:'给生活里的小尴尬换个角度',quote:'你准备早起，结果按了五次闹钟才起床。',context:'你想给朋友讲这件事，轻松一点，但不需要贬低自己，也不拿别人当笑料。',prompt:'写一两句轻松的表达。可以试试反差、拟人或适度夸张。',example:'我和闹钟进行了五轮友好协商，最终它同意我再睡一会儿。',action:'留意今天一个有画面感的小插曲，用一句轻松的话记录下来。',checks:[['建立具体画面','闹钟|被窝|床|五|早起|睡','从具体细节开始，让听的人能想象画面。'],['尝试视角转换','协商|谈判|上班|罢工|比赛|投降|坚持|签|会议|冠军|合作','试着把闹钟或被窝写成一个有性格的角色；其他表达也可能有效。'],['保留善意','废物|白痴|垃圾|蠢货','检查笑点是否需要靠贬低自己或他人才能成立。',true]]},
 {id:'listen',type:'communication',title:'朋友难过时，先不急着给建议',quote:'“我最近真的很累，感觉做什么都没意义。”',context:'朋友向你倾诉。你想支持他，但也不确定他现在需要倾听，还是一起想办法。',prompt:'你会如何回应，让对方感到被听见？',example:'听起来你最近撑得很辛苦。你愿意说说，最近哪件事让你最累吗？我可以先听你说，也可以和你一起想办法，你希望我怎么陪你？',action:'下一次倾听时，先复述你听到的感受，再问对方需要什么。',checks:[['回应感受','辛苦|累|难过|失落|不容易|听起来|感受','先回应对方的感受，不急着判断或解决。'],['询问对方需要','希望|需要|愿意|听|陪|说说|想','确认对方需要倾听还是建议。'],['避免否定情绪','想太多|这有什么|矫情|别难过|别人更惨','去掉可能让对方觉得不该有这种感受的话。',true]]}
];
const KEY='steady-practice-v1';
let storageOK=true;
function readState(){try{const s=JSON.parse(localStorage.getItem(KEY)||'{}');return {sessions:Array.isArray(s.sessions)?s.sessions:[],journals:Array.isArray(s.journals)?s.journals:[],drafts:s.drafts&&typeof s.drafts==='object'?s.drafts:{}}}catch{return {sessions:[],journals:[],drafts:{}}}}
let state=readState();let filter='all';let current=null;let stage=0;let firstAnswer='';let retryAnswer='';let previousHash='';
const main=document.querySelector('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;return true}catch{storageOK=false;toast('浏览器暂时无法保存，请先导出记录。');return false}}
let toastTimer;function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
const dateLabel=d=>new Date(d).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});
const localDay=d=>{const t=new Date(d);return `${t.getFullYear()}-${t.getMonth()+1}-${t.getDate()}`};
function shell(content){main.innerHTML=`<header class="topline"><span>给自己一点练习的时间</span><span class="local-badge"><i class="dot"></i>${storageOK?'记录保存在此浏览器':'浏览器保存不可用'}</span></header>${content}<footer class="footer"><span>从容 · 每天一小步，慢慢成为自己</span><a href="#about">训练方法与数据说明 ↗</a></footer>`}
function heading(en,title,sub,aside=''){return `<div class="heading"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${aside}</div>`}
function daily(){const n=Math.floor(Date.now()/86400000);return scenarios[n%6]}
function home(){const todayCount=state.sessions.filter(s=>localDay(s.date)===localDay(new Date())).length;shell(heading('A little practice, a little progress','让内心有力量，让表达有分寸。','从一个真实的情境开始，练习更清楚地思考、更从容地回应。',`<span class="date-note">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span>`)+`<section class="hero"><div><span class="pill">今日推荐 · ${categories[daily().type]}</span><h2>${daily().title}<br>你会怎么回应？</h2><p>不急着找标准答案。先听听自己的第一反应。</p><a class="primary" href="#practice/${daily().id}">${todayCount?'再练一个情境':'开始今天的练习'} <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit two"></div><div class="orbit"></div><div class="stone s1"></div><div class="stone s2"></div><div class="stone s3"></div><div class="sprout"></div><span class="art-caption">GROW AT YOUR OWN PACE</span></div></section><div class="section-head"><h2>你想从哪里开始？</h2><a href="#library">探索全部情境 ↗</a></div><section class="skills">${Object.entries(categories).map(([key,title],i)=>`<a class="skill-card" href="#library/${key}"><div class="skill-icon">${['⌘','❞','⌁','✧'][i]}</div><h3>${title}</h3><p>${['看清事实，做出自己的判断','理解彼此，也表达自己的边界','允许起伏，找到下一小步','换个角度，发现生活的轻盈'][i]}</p><div class="skill-foot"><span>${scenarios.filter(s=>s.type===key).length} 个练习情境</span><span>↗</span></div></a>`).join('')}</section><div class="lower-grid"><section class="panel"><h2>一次练习，四个小步骤</h2><div class="steps">${[['先回应','写下真实想法'],['看反馈','发现另一种可能'],['再试试','练习新的表达'],['带回生活','做一个微小行动']].map((s,i)=>`<div class="step"><span class="step-num">0${i+1}</span><b>${s[0]}</b>${s[1]}</div>`).join('')}</div></section><section class="panel"><div class="quote-mark">“</div><p class="quote">成长，是在熟悉的情境里，<br>多一种选择。</p><span class="tiny">今天已完成 ${todayCount} 次练习 · 累计 ${state.sessions.length} 次</span></section></div>`)}
function library(category){filter=categories[category]?category:'all';shell(heading('Practice library','生活，就是练习的场地。','选择一个熟悉的情境。从思考到表达，慢慢练出自己的方式。')+`<div class="filters">${[['all','全部情境'],...Object.entries(categories)].map(([key,title])=>`<a class="filter ${filter===key?'active':''}" href="#library${key==='all'?'':'/'+key}">${title}</a>`).join('')}</div><div class="scenario-grid">${scenarios.filter(s=>filter==='all'||s.type===filter).map(s=>`<article class="panel scenario-card"><span class="eyebrow">${categories[s.type]}</span><h2>${s.title}</h2><p>${s.context}</p><div class="card-bottom"><span class="tiny">约 5–10 分钟 · ${state.sessions.some(x=>x.scenarioId===s.id)?'已练习':'可随时开始'}</span><a class="text-button" href="#practice/${s.id}">开始练习 ↗</a></div></article>`).join('')}</div>`)}
function feedback(s,answer){return s.checks.map(([label,pattern,tip,invert])=>{const matched=new RegExp(pattern).test(answer);return {label,tip,seen:invert?!matched:matched,invert}})}
function practice(id){const s=scenarios.find(s=>s.id===id);if(!s){location.hash='#library';return}if(current?.id!==id||!previousHash.startsWith('#practice/')){current=s;stage=0;firstAnswer=state.drafts[id]||'';retryAnswer=''}shell(`<div class="workspace"><a class="breadcrumb" href="#library">← 返回情境训练库</a><div class="progress" aria-label="第 ${stage+1} 步，共 4 步">${[0,1,2,3].map(i=>`<span class="${i<=stage?'on':''}"></span>`).join('')}</div><div class="eyebrow">${categories[s.type]} · ${['先回应','看反馈','再试试','带回生活'][stage]}</div><h1>${s.title}</h1><section class="panel"><span class="pill">情境 ${String(scenarios.indexOf(s)+1).padStart(2,'0')}</span><p class="scenario-quote">${s.quote}</p><p class="context">${s.context}</p></section><div id="practice-step"></div></div>`);renderStep()}
function renderStep(){const s=current;const el=document.getElementById('practice-step');if(stage===0){el.innerHTML=`<form id="answer-form"><label class="label" for="answer">${s.prompt}</label><textarea id="answer" required maxlength="4000" placeholder="不用组织得很完美，先写下你此刻的想法……">${esc(firstAnswer)}</textarea><div class="actions"><span class="hint">先作答，再看参考。草稿自动保存在此浏览器。</span><button class="primary" type="submit">看看练习反馈 →</button></div></form>`;document.getElementById('answer').addEventListener('input',e=>{firstAnswer=e.target.value;state.drafts[s.id]=firstAnswer;persist()});document.getElementById('answer-form').onsubmit=e=>{e.preventDefault();firstAnswer=document.getElementById('answer').value.trim();if(!firstAnswer){toast('先写下一点想法，再继续。');return}stage=1;practice(s.id)}}
 else if(stage===1){el.innerHTML=`<section class="panel" style="margin-top:20px"><span class="practice-badge">规则辅助 · 不是 AI 语义评价</span><h2 style="margin-top:10px">给这次回答，几个观察角度</h2><p class="hint">以下提示只检查词语线索，可能漏掉你的意思。请结合情境自行判断。</p><div class="saved-answer">${esc(firstAnswer)}</div>${feedback(s,firstAnswer).map(f=>`<div class="feedback-item"><div class="feedback-title">${f.seen?'↗ 可以进一步检查':'○ 值得留意'} · ${f.label}</div><p>${f.seen?(f.invert?'没有检测到预设的对抗或贬低词语；仍请检查语气和语境。':'检测到相关表达线索；再看看是否具体、自然，适合这个场合。'):f.tip}</p></div>`).join('')}<details><summary>看一种参考思路（不是标准答案）</summary><div class="example">${s.example}</div></details><div class="actions"><button class="text-button" id="back">← 修改原回答</button><button class="primary" id="next">换一种方式，再试试 →</button></div></section>`;document.getElementById('back').onclick=()=>{stage=0;practice(s.id)};document.getElementById('next').onclick=()=>{stage=2;practice(s.id)}}
 else if(stage===2){el.innerHTML=`<form id="retry-form"><label class="label" for="retry">保留你的风格，试着写一个新的版本。</label><textarea id="retry" required maxlength="4000" placeholder="如果再遇到一次，你想怎么回应？">${esc(retryAnswer)}</textarea><details><summary>回看我的第一反应</summary><div class="saved-answer">${esc(firstAnswer)}</div></details><div class="actions"><button class="text-button" type="button" id="back">← 回看反馈</button><button class="primary" type="submit">把练习带回生活 →</button></div></form>`;document.getElementById('retry').oninput=e=>{retryAnswer=e.target.value};document.getElementById('back').onclick=()=>{stage=1;practice(s.id)};document.getElementById('retry-form').onsubmit=e=>{e.preventDefault();retryAnswer=document.getElementById('retry').value.trim();if(!retryAnswer){toast('写下你的新版本，再继续。');return}stage=3;practice(s.id)}}
 else{el.innerHTML=`<form id="finish-form" class="panel" style="margin-top:20px"><h2>让一个小改变，真的发生。</h2><div class="note">行动灵感：${s.action}</div><label class="label" for="takeaway">这次你发现了什么？</label><textarea id="takeaway" maxlength="2000" style="min-height:90px" placeholder="例如：我可以先问具体问题，不必马上证明自己。"></textarea><label class="label" for="action">接下来准备尝试的一个小行动</label><input id="action" required maxlength="500" placeholder="写得具体一点：在什么情境下，做什么？"><div class="actions"><button class="text-button" type="button" id="back">← 修改新版本</button><button class="primary" type="submit">完成并保存练习 ✓</button></div></form>`;document.getElementById('back').onclick=()=>{stage=2;practice(s.id)};document.getElementById('finish-form').onsubmit=e=>{e.preventDefault();const action=document.getElementById('action').value.trim();if(!action){toast('写下一个小行动，帮助自己开始。');return}const item={id:crypto.randomUUID(),date:new Date().toISOString(),scenarioId:s.id,title:s.title,type:s.type,firstAnswer,retryAnswer,takeaway:document.getElementById('takeaway').value.trim(),action,done:false};state.sessions.unshift(item);delete state.drafts[s.id];persist();current=null;location.hash='#review';toast(storageOK?'这次练习已保存。慢慢来，你已经迈出一步。':'练习暂存在当前页面，请导出记录以免丢失。')}}}
function journal(){shell(heading('Reflect on real life','把经历，变成经验。','记录一个真实片段。把事实、感受和解释分开，找到下一次可以尝试的选择。')+`<div class="journal-layout"><form id="journal-form" class="panel"><label class="label" for="event-title" style="margin-top:0">给这次经历起个名字</label><input id="event-title" required maxlength="100" placeholder="例如：今天没有及时表达的那个想法"><label class="label" for="facts">发生了什么？只描述可观察的事实。</label><textarea id="facts" required maxlength="3000" placeholder="谁说了什么、做了什么？先不判断动机。"></textarea><label class="label" for="feelings">我有什么感受？当时怎样理解这件事？</label><textarea id="feelings" required maxlength="3000" style="min-height:100px" placeholder="我感到……我当时以为……"></textarea><label class="label" for="alternative">还有什么可能的解释？</label><textarea id="alternative" maxlength="2000" style="min-height:90px" placeholder="有没有我不知道的信息？对方还可能在担心什么？"></textarea><label class="label" for="next-action">下次，我想尝试什么？</label><input id="next-action" required maxlength="500" placeholder="一个具体、可控的小行动"><div class="actions"><span class="hint">只保存到此浏览器。</span><button type="submit" class="primary">保存这次复盘 ✓</button></div></form><aside class="panel journal-help"><div class="eyebrow">A gentler perspective</div><h2 style="margin-top:13px">给自己留一点空间</h2><ol><li>“他没有回复”是事实；“他不尊重我”是解释。</li><li>感受不需要被证明合理。先给它一个名字。</li><li>找到自己的可控部分，也允许自己休息、求助和设定边界。</li><li>复盘的目的是找到选择，不是给自己判分。</li></ol><p class="tiny">复盘未提交的草稿也会自动保存。</p></aside></div>`);const fields=['event-title','facts','feelings','alternative','next-action'];const draft=state.drafts.journal||{};for(const id of fields){const el=document.getElementById(id);el.value=draft[id]||'';el.oninput=()=>{state.drafts.journal=Object.fromEntries(fields.map(k=>[k,document.getElementById(k).value]));persist()}}document.getElementById('journal-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(fields.map(k=>[k,document.getElementById(k).value.trim()]));if(['event-title','facts','feelings','next-action'].some(k=>!data[k])){toast('请补充事实、感受和下一步行动。');return}state.journals.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),...data});delete state.drafts.journal;persist();location.hash='#review';toast(storageOK?'复盘已保存。':'请导出记录，保存到文件。')}}
function review(){const cutoff=Date.now()-7*86400000;const week=state.sessions.filter(s=>new Date(s.date).getTime()>=cutoff);const days=new Set(state.sessions.map(s=>localDay(s.date))).size;shell(heading('Your growth, in small steps','看见每一次，认真尝试。','这里记录你的练习和行动。没有人格评分，只有真实留下的脚印。',`<button class="secondary" id="export">导出我的记录 ↓</button>`)+`<div class="stats"><div class="stat"><strong>${state.sessions.length}</strong><span>累计情境练习</span></div><div class="stat"><strong>${state.journals.length}</strong><span>真实事件复盘</span></div><div class="stat"><strong>${days}</strong><span>留下练习的日子</span></div></div><section class="panel"><h2>最近七天的小回顾</h2><p class="context">${week.length?`你完成了 ${week.length} 次练习，涉及 ${new Set(week.map(s=>s.type)).size} 个方向。挑一个小行动尝试，再记录实际结果。`:'还没有最近的练习记录。从一个你熟悉的情境开始就好。'}</p><a class="text-button" href="#library">去做一次练习 ↗</a></section><div class="section-head"><h2>练习与行动</h2><span class="tiny">勾选表示你已在现实中尝试</span></div>${state.sessions.length?state.sessions.map(s=>`<article class="panel entry"><span class="tiny">${dateLabel(s.date)} · ${esc(categories[s.type]||s.type)}</span><h3>${esc(s.title)}</h3><p><b>准备尝试：</b>${esc(s.action)}</p><label class="hint"><input type="checkbox" data-done="${esc(s.id)}" ${s.done?'checked':''} style="width:auto;margin-right:7px">我在现实中尝试过这个行动</label><details><summary>回看回答和收获</summary><p><b>最初的回答</b></p><div class="saved-answer">${esc(s.firstAnswer)}</div><p style="margin-top:15px"><b>重新尝试</b></p><div class="saved-answer">${esc(s.retryAnswer)}</div><p><b>我的发现：</b>${esc(s.takeaway||'暂未记录')}</p></details><button class="text-button" data-delete-session="${esc(s.id)}">删除这条记录</button></article>`).join(''):`<div class="panel empty"><h2>第一步，还在等你。</h2><p>完成一次练习后，你的回答和行动会出现在这里。</p><a class="primary" href="#library">选择一个情境 ↗</a></div>`}<div class="section-head"><h2>真实事件复盘</h2><a href="#journal">写一条新复盘 ↗</a></div>${state.journals.length?state.journals.map(j=>`<article class="panel entry"><span class="tiny">${dateLabel(j.date)}</span><h3>${esc(j['event-title'])}</h3><details><summary>展开复盘</summary>${[['facts','发生的事实'],['feelings','感受与当时的解释'],['alternative','其他可能'],['next-action','下一步行动']].map(([k,l])=>`<p><b>${l}</b><br>${esc(j[k]||'暂未记录')}</p>`).join('')}</details><button class="text-button" data-delete-journal="${esc(j.id)}">删除这条复盘</button></article>`).join(''):`<p class="context">还没有复盘记录。生活里一个很小的片段，也值得记下来。</p>`}`);document.getElementById('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`从容-成长记录-${localDay(new Date())}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('记录已导出，请妥善保存文件。')};document.querySelectorAll('[data-done]').forEach(el=>el.onchange=()=>{const s=state.sessions.find(s=>s.id===el.dataset.done);s.done=el.checked;persist()});for(const [attr,list] of [['deleteSession','sessions'],['deleteJournal','journals']])document.querySelectorAll(`[data-${attr==='deleteSession'?'delete-session':'delete-journal'}]`).forEach(el=>el.onclick=()=>{if(!confirm('确定删除这条记录吗？此操作无法撤销。'))return;state[list]=state[list].filter(s=>s.id!==el.dataset[attr]);persist();review();toast('记录已删除。')})}
function about(){shell(heading('About this practice','练习能力，也尊重自己的节奏。','这是一个个人练习工具。第一版提供情境、规则辅助提示、重试和本地复盘。')+`<section class="panel sources"><h2>为什么这样练？</h2><p>先自己组织回答，再看提示，最后换一种方式尝试。不同日期重复练习相似技能，帮助你主动回忆方法，而不只是阅读方法。</p><p>主动回忆和间隔练习有较好的学习研究支持，但记住技巧并不保证能在真实冲突中运用。因此，每次练习都以一个现实小行动收尾。</p><p><a href="https://www.learningscientists.org/retrieval-practice" target="_blank" rel="noopener">了解主动回忆 ↗</a> · <a href="https://www.learningscientists.org/spaced-practice" target="_blank" rel="noopener">了解间隔练习 ↗</a></p><h2>反馈能做什么？</h2><p>当前没有接入 AI 模型。反馈基于预设词语线索，不能判断你的真实意图、人格、情商或心理状态。未匹配某个词，不代表你没做到；匹配到某个词，也不代表回答有效。参考表达只提供一种思路。</p><h2>恢复，也是能力的一部分</h2><p>压力练习包含休息、寻求支持和调整工作范围。你可以跳过任何不适合自己的情境，不需要连续打卡，也不需要完成所有练习。</p><p><a href="https://www.apa.org/topics/resilience/building-your-resilience" target="_blank" rel="noopener">美国心理学会：建立韧性 ↗</a></p><h2>我的数据在哪里？</h2><p>回答、草稿和复盘保存在当前浏览器的本地存储中，不上传到服务器，也不会跨设备同步。清理浏览器数据或使用隐私模式可能导致记录丢失。你可以在成长记录页导出 JSON 文件。外部字体加载可能向字体服务发送常规网络请求。</p><a class="primary" href="#library">开始一次练习 ↗</a></section>`)}
function route(){const hash=location.hash||'#home';const [page,arg]=hash.slice(1).split('/');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(page==='practice'?'library':page)));switch(page){case 'library':library(arg);break;case 'practice':practice(arg);break;case 'journal':journal();break;case 'review':review();break;case 'about':about();break;default:home()}previousHash=hash;window.scrollTo({top:0,behavior:'instant'})}
window.addEventListener('hashchange',route);route();
